(3074, 1, 'skin_msg', '\n<tr>\n  <td class=\'row1 align=\'left\' valign=\'middle\'><a href=\'{$ibforums->base_url}act=Profile&amp;CODE=03&amp;MID={$entry[\'contact_id\']}\'><b>{$entry[\'contact_name\']}</b></a> &nbsp; &nbsp;[ {$entry[\'contact_desc\']} ]</td>\n  <td class=\'row1 align=\'left\' valign=\'middle\'>\n	   [ <a href=\'{$ibforums->base_url}act=Msg&amp;CODE=11&amp;MID={$entry[\'contact_id\']}\'>{$ibforums->lang[\'edit\']}</a> ] :: [ <a href=\'{$ibforums->base_url}act=Msg&amp;CODE=10&amp;MID={$entry[\'contact_id\']}\'>{$ibforums->lang[\'delete\']}</a> ]\n		&nbsp;&nbsp;( {$entry[\'text\']} )\n  </td>\n</tr>\n', 'render_address_row', '$entry', 1779380963, 0),
