(3103, 1, 'skin_global', '\n<table width=\"100%\" id=\"userlinks\" cellspacing=\"6\">\n   <tr>\n    <td><strong>{$ibforums->lang[\'logged_in_as\']} <a href=\'{$ibforums->base_url}showuser={$ibforums->member[\'id\']}\'>{$ibforums->member[\'name\']}</a></strong> ( <a href=\'{$ibforums->base_url}act=Login&amp;CODE=03\'>{$ibforums->lang[\'log_out\']}</a>$ad_link $mod_link $val_link )</td>\n    <td align=\'right\'>\n      <b><a href=\'{$ibforums->base_url}act=UserCP&amp;CODE=00\' title=\'{$ibforums->lang[\'cp_tool_tip\']}\'>{$ibforums->lang[\'your_cp\']}</a></b> &middot; <a href=\'{$ibforums->base_url}act=Msg&amp;CODE=01\'>{$msg[\'TEXT\']}</a>\n      &middot; <a href=\'{$ibforums->base_url}act=Search&amp;CODE=getnew\'>{$ibforums->lang[\'view_new_posts\']}</a> &middot; <a href=\'javascript:buddy_pop();\' title=\'{$ibforums->lang[\'bb_tool_tip\']}\'>{$ibforums->lang[\'l_qb\']}</a></td>\n   </tr>\n  </table>\n', 'Member_bar', '$msg, $ad_link, $mod_link, $val_link', 1779380963, 0),
(3104, 1, 'skin_global', '\n<table width=\"100%\" id=\"userlinks\" cellspacing=\"6\">\n   <tr>\n    <td>{$ibforums->lang[\'guest_stuff\']} ( <a href=\'{$ibforums->base_url}act=Login&amp;CODE=00\'>{$ibforums->lang[\'log_in\']}</a> | <a href=\'{$ibforums->base_url}act=Reg&amp;CODE=00\'>{$ibforums->lang[\'register\']}</a> )</td>\n    <td align=\'right\'><a href=\'{$ibforums->base_url}act=Reg&amp;CODE=reval\'>{$ibforums->lang[\'ml_revalidate\']}</a></td>\n   </tr>\n  </table>\n', 'Guest_bar', '', 1779380963, 0),
