(3106, 1, 'skin_global', '\n<table width=\"100%\" id=\"userlinks\" cellspacing=\"6\">\n   <tr>\n    <td><b>{$ibforums->lang[\'logged_in_as\']} {$ibforums->member[\'name\']}</b> ( <a href=\'{$ibforums->base_url}act=Login&amp;CODE=03\'>{$ibforums->lang[\'log_out\']}</a>$ad_link $mod_link $val_link )</td>\n    <td align=\'right\'>\n   <b><a href=\'{$ibforums->base_url}act=UserCP&amp;CODE=00\' title=\'{$ibforums->lang[\'cp_tool_tip\']}\'>{$ibforums->lang[\'your_cp\']}</a></b>\n    &middot;  <a href=\'{$ibforums->base_url}act=Search&amp;CODE=getnew\'>{$ibforums->lang[\'view_new_posts\']}</a>  &middot;  <a href=\'javascript:buddy_pop();\' title=\'{$ibforums->lang[\'bb_tool_tip\']}\'>{$ibforums->lang[\'l_qb\']}</a></td>\n   </tr>\n  </table>\n', 'Member_no_usepm_bar', '$ad_link, $mod_link, $val_link', 1779380963, 0),
(3107, 1, 'skin_global', '\n<script language=\'JavaScript\' type=\"text/javascript\">\n<!--\nfunction buddy_pop() { window.open(\'index.{$ibforums->vars[\'php_ext\']}?act=buddy&s={$ibforums->session_id}\',\'BrowserBuddy\',\'width=250,height=500,resizable=yes,scrollbars=yes\'); }\nfunction chat_pop(cw,ch)  { window.open(\'index.{$ibforums->vars[\'php_ext\']}?s={$ibforums->session_id}&act=chat&pop=1\',\'Chat\',\'width=\'+cw+\',height=\'+ch+\',resizable=yes,scrollbars=yes\'); }\nfunction multi_page_jump( url_bit, total_posts, per_page )\n{\npages = 1; cur_st = parseInt(\"{$ibforums->input[\'st\']}\"); cur_page  = 1;\nif ( total_posts % per_page == 0 ) { pages = total_posts / per_page; }\n else { pages = Math.ceil( total_posts / per_page ); }\nmsg = \"{$ibforums->lang[\'tpl_q1\']}\" + \" \" + pages;\nif ( cur_st > 0 ) { cur_page = cur_st / per_page; cur_page = cur_page -1; }\nshow_page = 1;\nif ( cur_page < pages )  { show_page = cur_page + 1; }\nif ( cur_page >= pages ) { show_page = cur_page - 1; }\n else { show_page = cur_page + 1; }\nuserPage = prompt( msg, show_page );\nif ( userPage > 0  ) {\n	if ( userPage < 1 )     {    userPage = 1;  }\n	if ( userPage > pages ) { userPage = pages; }\n	if ( userPage == 1 )    {     start = 0;    }\n	else { start = (userPage - 1) * per_page; }\n	window.location = url_bit + \"&st=\" + start;\n}\n}\n//-->\n</script>\n \n<!--IBF.BANNER-->\n<div id=\'logostrip\'>\n  <div class=\"header-container\">\n    <a href=\'{$ibforums->base_url}\' title=\'Board Home\' class=\"logo-link\">{$ibforums->vars[\'board_name\']}</a>\n    \n    <div class=\"search-toggle-btn\" onclick=\"toggleSearchBox()\">\n        <i class=\"fa-solid fa-magnifying-glass\"></i>\n    </div>\n  </div>\n</div>\n<div id=\"search-dropdown-row\" class=\"search-row-hidden\">\n    <form action=\"/index.php?act=Search&CODE=01\" method=\"post\" class=\"search-flex-container\">\n        <input type=\"hidden\" name=\'forums\' value=\"all\">\n        <input type=\"hidden\" name=\'search_in\' value=\'posts\'>\n        <input type=\"hidden\" name=\'result_type\' value=\'topics\'>\n        \n        <div class=\"search-input-wrapper\">\n            <i class=\"fa-solid fa-magnifying-glass input-icon\"></i>\n            <input type=\'text\' maxlength=\'100\' name=\'keywords\' class=\'modern-input\' placeholder=\'Search...\'>\n            <input type=\'submit\' value=\'Search\' class=\'modern-submit\'>\n        </div>\n    </form>\n</div>\n<!-- IE6/Win TABLE FIX -->\n<table  width=\"100%\" cellspacing=\"6\" id=\"submenu\">\n<tr>\n <td><a href=\'{$ibforums->vars[\'home_url\']}\'>{$ibforums->vars[\'home_name\']}</a><!--IBF.RULES--></td>\n <td align=\"right\">\n \n   <i class=\"fa-solid fa-circle-question\" style=\"color: #3498db;\"></i>&nbsp;<a href=\'{$ibforums->base_url}act=Help\'>{$ibforums->lang[\'tb_help\']}</a>\n     &nbsp;&nbsp;&nbsp;<i class=\"fa-solid fa-magnifying-glass\" style=\"color: #2ecc71;\"></i>&nbsp;<a href=\'{$ibforums->base_url}act=Search&amp;f={$ibforums->input[\'f\']}\'>{$ibforums->lang[\'tb_search\']}</a>\n{member_only}\n    &nbsp;&nbsp;&nbsp;<i class=\"fa-solid fa-users\" style=\"color: #9b59b6;\"></i>&nbsp;<a href=\'{$ibforums->base_url}act=Members\'>{$ibforums->lang[\'tb_mlist\']}</a>\n    &nbsp;&nbsp;&nbsp;<i class=\"fa-solid fa-star\" style=\"color: #e74c3c;\"></i>&nbsp;<a href=\'{$ibforums->base_url}act=rep&CODE=totals\'>{$ibforums->lang[\'rep_name\']}</a>\n    &nbsp;&nbsp;&nbsp;<i class=\"fa-solid fa-bookmark\" style=\"color: #f39c12;\"></i>&nbsp;<a href=\'{$ibforums->base_url}act=fav\'>Favorites</a>\n{/member_only}\n&nbsp;&nbsp;&nbsp;<i class=\"fa-solid fa-calendar-days\" style=\"color: #1abc9c;\"></i>&nbsp;<a href=\'{$ibforums->base_url}act=calendar\'>{$ibforums->lang[\'tb_calendar\']}</a>\n\n   <!--IBF.CHATLINK-->\n   <!--IBF.TSLLINK-->\n </td>\n</tr>\n</table>\n<% MEMBER BAR %>\n<br />\n', 'BoardHeader', '$time=\"\"', 1779380963, 0),
