(3248, 1, 'skin_boards', '\n	<div class=\"tableborder\">\n	  <div class=\'maintitle\' align=\'left\'><{CAT_IMG}>&nbsp;{$ibforums->lang[\'welcome_guest\']} <a href=\"{$ibforums->base_url}&amp;act=Login&amp;CODE=00\"><u>{$ibforums->lang[\'wel_login\']}</u></a> {$ibforums->lang[\'wel_or\']} <a href=\"{$ibforums->base_url}&amp;act=Reg&amp;CODE=00\"><u>{$ibforums->lang[\'wel_reg\']}</u></a>!</div>\n      <table width=\"100%\" border=\"0\" cellspacing=\"1\" cellpadding=\"4\">\n        <tr> \n          <td class=\"row4\"><span class=\"avatar\"><img src=\'{$ibforums->vars[\'board_url\']}/html/avatars/default.svg\' border=\'0\' alt=\'{$ibforums->lang[\'av_not_sel\']}\' /></span></td>\n          <td class=\"row2\" width=\"100%\">{$ibforums->lang[\'its_now\']} {$data[\'time\']}<br />\n		  {$ibforums->lang[\'today_thbeen\']} {$data[\'posts_scince\']} {$ibforums->lang[\'posts_in\']} {$data[\'topics_scince\']} topics<br />\n		  <a href=\"{$ibforums->base_url}act=Search&amp;CODE=getactive\">{$ibforums->lang[\'sm_todays_posts\']}</a><br />\n		  {$ibforums->lang[\'most_online\']}\n          </td>\n          <td class=\"row4\" align=\"right\">\n		  <form style=\'display:inline\' action=\"{$ibforums->base_url}act=Login&amp;CODE=01&amp;CookieDate=1\" method=\"post\">\n		    <table border=\"0\" cellspacing=\"0\" cellpadding=\"1\">\n			  <tr>\n			    <!--<td>{$ibforums->lang[\'youname\']}:&nbsp;</td>-->\n				<td><input type=\"text\" class=\"forminput\" size=\"20\" name=\"UserName\" onfocus=\"this.value=\'\'\" value=\"{$ibforums->lang[\'qli_name\']}\" /></td>\n			  </tr>\n			  <tr>\n			    <!--<td>{$ibforums->lang[\'youpasswd\']}:&nbsp;</td>-->\n				<td><input type=\'password\' class=\'forminput\' size=\'20\' name=\'PassWord\' onfocus=\"this.value=\'\'\" value=\'ibfrules!\' /></td>\n			  </tr>\n			</table>\n				<div align=\"center\"><input type=\'submit\' class=\'forminput\' value=\'{$ibforums->lang[\'log_me\']}\' /></div>\n		  </form>\n          </td>\n        </tr>\n      </table>\n    </div>\n    <br />\n', 'GuestPanel', '$data=\"\"', 1779380964, 0),
(3249, 1, 'skin_online', '\n              <!-- Entry for {$session[\'member_id\']} -->\n              <tr>\n                <td class=\'row1\'>{$session[\'member_name\']}</td>\n                <td class=\'row1\'>{$session[\'where_line\']}</td>\n                <td class=\'row1\' align=\'center\'>{$session[\'running_time\']}</td>\n                <td class=\'row1\' align=\'center\'>{$session[\'msg_icon\']}</td>\n              </tr>\n              <!-- End of Entry -->\n', 'show_row', '$session', 1779380964, 0),
