INSERT INTO `ibf_skin_templates` (`suid`, `set_id`, `group_name`, `section_content`, `func_name`, `func_data`, `updated`, `can_remove`) VALUES
(3316, 1, 'skin_login', '\n<script language=\'JavaScript\' type=\"text/javascript\">\n<!--\nfunction ValidateForm() {\n	var Check = 0;\n	if (document.LOGIN.UserName.value == \'\') { Check = 1; }\n	if (document.LOGIN.PassWord.value == \'\') { Check = 1; }\n	if (Check == 1) {\n		alert(\"{$ibforums->lang[\'blank_fields\']}\");\n		return false;\n	} else {\n		document.LOGIN.submit.disabled = true;\n		return true;\n	}\n}\n//-->\n</script>     \n{$ibforums->lang[\'login_text\']}\n<br />\n<br />\n<b>{$ibforums->lang[\'forgot_pass\']} <a href=\'{$ibforums->vars[\'board_url\']}/index.{$ibforums->vars[\'php_ext\']}?act=Reg&amp;CODE=10\'>{$ibforums->lang[\'pass_link\']}</a></b>\n<br />\n<br />\n<form action=\"{$ibforums->base_url}act=Login&amp;CODE=01\" method=\"post\" name=\'LOGIN\' onsubmit=\'return ValidateForm()\'>\n<input type=\'hidden\' name=\'referer\' value=\"$referer\" />\n<div class=\"tableborder\">\n  <div class=\"maintitle\"><{CAT_IMG}>&nbsp;{$ibforums->lang[\'log_in\']}</div>\n  <div class=\'pformstrip\'>$message</div>\n  <table class=\"tablebasic\" cellspacing=\"1\">\n  <tr>\n    <td class=\'pformleftw\'>{$ibforums->lang[\'enter_name\']}</td>\n    <td class=\'pformright\'><input type=\'text\' size=\'20\' maxlength=\'64\' name=\'UserName\' class=\'forminput\' /></td>\n  </tr>\n  <tr>\n    <td class=\'pformleftw\'>{$ibforums->lang[\'enter_pass\']}</td>\n    <td class=\'pformright\'><input type=\'password\' size=\'20\' name=\'PassWord\' class=\'forminput\' /></td>\n  </tr>\n  </table>\n  <div class=\"pformstrip\">{$ibforums->lang[\'options\']}</div>		\n  <table class=\"tablebasic\" cellspacing=\"1\">\n  <tr>\n    <td class=\'pformleftw\'>{$ibforums->lang[\'cookies\']}</td>\n    <td class=\'pformright\'><input type=\"radio\" name=\"CookieDate\" value=\"1\" checked=\"checked\" />{$ibforums->lang[\'cookie_yes\']}<br /><input type=\"radio\" name=\"CookieDate\" value=\"0\" />{$ibforums->lang[\'cookie_no\']}</td>\n  </tr>\n  <tr>\n    <td class=\'pformleftw\'>{$ibforums->lang[\'privacy\']}</td>\n    <td class=\'pformright\'><input type=\"checkbox\" name=\"Privacy\" value=\"1\" />{$ibforums->lang[\'anon_name\']}</td>\n  </tr>\n  </table>		\n  <div class=\"pformstrip\" align=\"center\"><input type=\"submit\" name=\'submit\' value=\"{$ibforums->lang[\'log_in_submit\']}\" class=\'forminput\' /></div>\n</div>\n</form>\n', 'ShowForm', '$message, $referer=\"\"', 1779380964, 0),
(3317, 1, 'skin_printpage', '\n<div class=\'tableborder\'>\n <div class=\'maintitle\'><{CAT_IMG}>&nbsp;{$ibforums->lang[\'tvo_title\']}&nbsp;$title</div>\n <div class=\'tablepad\'>\n  <b><a href=\'{$ibforums->base_url}act=Print&amp;client=printer&amp;f=$fid&amp;t=$tid\'>{$ibforums->lang[\'o_print_title\']}</a></b>\n  <br />\n  {$ibforums->lang[\'o_print_desc\']}\n  <br /><br />\n  <b><a href=\'{$ibforums->base_url}act=Print&amp;client=html&amp;f=$fid&amp;t=$tid\'>{$ibforums->lang[\'o_html_title\']}</a></b>\n  <br />\n  {$ibforums->lang[\'o_html_desc\']}\n  <br /><br />\n  <b><a href=\'{$ibforums->base_url}act=Print&amp;client=wordr&amp;f=$fid&amp;t=$tid\'>{$ibforums->lang[\'o_word_title\']}</a></b>\n  <br />\n  {$ibforums->lang[\'o_word_desc\']}\n </div>\n <div align=\'center\' class=\'pformstrip\'>&lt;&lt;<a href=\'{$ibforums->base_url}showtopic=$tid\'>{$ibforums->lang[\'back_topic\']}</a></div>\n</div>\n<br />\n', 'choose_form', '$fid, $tid, $title', 1779380964, 0),
(3318, 1, 'skin_printpage', '\n	<table width=\'90%\' align=\'center\' cellpadding=\'6\' border=\'1\'>\n	<tr>\n	 <td bgcolor=\'#EEEEEE\'><font face=\'arial\' size=\'2\' color=\'#000000\'><b>{$ibforums->lang[\'by\']}: {$entry[\'author_name\']}</b> {$ibforums->lang[\'on\']} {$entry[\'post_date\']}</b></font></td>\n	</tr>\n	<tr>\n	 <td><font face=\'arial\' size=\'3\' color=\'#000000\'>{$entry[\'post\']}</font></td>\n	</tr>\n	</table>\n	<br />\n', 'pp_postentry', '$poster, $entry', 1779380964, 0),
