(3320, 1, 'skin_printpage', '\n    <html>\n    <head>\n      <title>{$ibforums->vars[\'board_name\']} [Powered by Invision Power Board]</title>\n	<META http-equiv=\"Content-Type\" content=\"text/html;charset=windows-1251\">\n    </head>\n    <body bgcolor=\'#FFFFFF\' alink=\'#000000\' vlink=\'#000000\' link=\'#000000\'>\n     <table width=\'90%\' border=\'0\' align=\'center\' cellpadding=\'6\'>\n      <tr>\n       <td><b><font face=\'arial\' size=\'5\' color=\'#4C77B6\'><b>{$ibforums->lang[\'title\']}</font></b>\n       	   <br /><font face=\'arial\' size=\'2\' color=\'#000000\'><b><a href=\'{$ibforums->base_url}act=ST&amp;f=$fid&amp;t=$tid\'>{$ibforums->lang[\'topic_here\']}</a></b></font>\n       </td>\n      </tr>\n      <tr>\n       <td><font face=\'arial\' size=\'2\' color=\'#000000\'><b>{$ibforums->vars[\'board_name\']} &gt; $forum_name &gt; <font color=\'red\'>$topic_title</font></b></font></td>\n      </tr>\n     </table>\n     <br />\n     <br />\n', 'pp_header', '$forum_name, $topic_title, $topic_starter,$fid, $tid', 1779380964, 0),
(3321, 1, 'skin_ucp', '\n<script language=\"javascript\" type=\"text/javascript\">\n<!--\n	var url_input      = \"$url_photo\";\n	var remove_pressed = 0;\n	\n	function clear_it()\n	{\n		if ( document.bob.url_photo.value != \"\" )\n		{\n			url_input = document.bob.url_photo.value;\n		}\n      \n		document.bob.url_photo.value = \"\";\n	}\n   \n	function restore_it()\n	{\n		if (url_input != \"\")\n		{\n			document.bob.url_photo.value = url_input;\n		}\n	}\n   \n	function checkform()\n	{\n   		if ( remove_pressed != 1 )\n   		{\n   			return true;\n   		}\n   		else\n   		{\n   			fcheck = confirm(\"{$ibforums->lang[\'pp_confirm\']}\");\n   			if ( fcheck == true )\n   			{\n   				return true;\n   			}\n   			else\n   			{\n   				return false;\n   			}\n   		}\n	}\n//-->\n</script>\n<form action=\"{$ibforums->base_url}auth_key=$key\" enctype=\'multipart/form-data\' method=\"post\" name=\"bob\" onsubmit=\"return checkform();\">\n<input type=\'hidden\' name=\'act\' value=\'UserCP\' />\n<input type=\'hidden\' name=\'CODE\' value=\'dophoto\' />\n<div class=\"pformstrip\">{$ibforums->lang[\'pph_title\']}</div>\n<p>{$ibforums->lang[\'pph_desc\']}<br />{$ibforums->lang[\'pph_max\']}</p>\n<div class=\"pformstrip\">{$ibforums->lang[\'pph_current\']}</div>\n<div align=\"center\">\n <p>$cur_photo<br />$cur_type $show_size</p>\n</div>\n<div class=\"pformstrip\">{$ibforums->lang[\'pph_change\']}</div>\n<table class=\'tablebasic\' cellpadding=\'4\'>\n<tr>\n <td class=\'pformleft\'>{$ibforums->lang[\'pph_url\']}</td>\n <td class=\'pformright\'><input type=\'text\' onfocus=\"restore_it()\" name=\'url_photo\' value=\'$url_photo\' size=\'40\' class=\'forminput\' />&nbsp;&nbsp;(<a href=\'javascript:restore_it()\'>{$ibforums->lang[\'pp_restore\']}</a>)</td>\n</tr>\n<!--IPB.UPLOAD-->\n<!--IPB.SIZE-->\n</table>\n<div align=\"center\" class=\"pformstrip\">\n  <input type=\"submit\" name=\'submit\' value=\"{$ibforums->lang[\'pph_submit\']}\" class=\'forminput\' />\n  &nbsp;&nbsp;&nbsp;&nbsp;