(3352, 1, 'skin_ucp', '\n<!--\nTABLE TO FIX IE/6 ISSUE\nThe one where 23% margin + 100% table = 123% in IE6 o_O\n-->\n<table cellspacing=\"0\" cellpadding=\"0\" width=\'100%\'>\n<tr>\n <td id=\"ucpmenu\" valign=\"top\">\n    <div class=\'maintitle\'>{$ibforums->lang[\'tt_menu\']}</div>\n     <!--IBF.TSLLINKS-->\n	 <!-- Messenger -->\n	 <div class=\'pformstrip\'>{$ibforums->lang[\'m_messenger\']}</div>\n	 <p>\n	 &middot; <a href=\'{$base_url}act=Msg&amp;CODE=04\'><strong>{$ibforums->lang[\'mess_new\']}</strong></a><br />\n	 &middot; <a href=\'{$base_url}act=Msg&amp;CODE=01\'><strong>{$ibforums->lang[\'mess_inbox\']}</strong></a><br />\n	 <!--IBF.FOLDER_LINKS-->\n	 &middot; <a href=\'{$base_url}act=Msg&amp;CODE=delete\'>{$ibforums->lang[\'mi_prune_msg\']}</a><br />\n	  &middot; <a href=\'{$base_url}act=Msg&amp;CODE=07\'>{$ibforums->lang[\'mess_folders\']}</a><br />\n	 &middot; <a href=\'{$base_url}act=Msg&amp;CODE=02\'>{$ibforums->lang[\'mess_contact\']}</a><br />\n	 &middot; <a href=\'{$base_url}act=Msg&amp;CODE=14\'>{$ibforums->lang[\'mess_archive\']}</a><br />\n	 &middot; <a href=\'{$base_url}act=Msg&amp;CODE=20\'>{$ibforums->lang[\'mess_saved\']}</a><br />\n	 &middot; <a href=\'{$base_url}act=Msg&amp;CODE=30\'>{$ibforums->lang[\'mess_tracker\']}</a><br />\n	 </p>\n	 <!-- End Messenger -->\n	 <!-- Topic Tracker -->\n	 <div class=\'pformstrip\'>{$ibforums->lang[\'m_tracker\']}</div>\n	 <p>\n	 &middot; <a href=\'{$base_url}act=UserCP&amp;CODE=26\'>{$ibforums->lang[\'m_view_subs\']}</a><br />\n	 &middot; <a href=\'{$base_url}act=UserCP&amp;CODE=50\'>{$ibforums->lang[\'m_view_forum\']}</a><br />\n	 </p>\n	 <!-- Profile -->\n	 <div class=\'pformstrip\'>{$ibforums->lang[\'m_personal\']}</div>\n	 <p>\n	 &middot; <a href=\'{$base_url}act=UserCP&amp;CODE=01\'>{$ibforums->lang[\'m_contact_info\']}</a><br />\n	 &middot; <a href=\'{$base_url}act=UserCP&amp;CODE=22\'>{$ibforums->lang[\'m_sig_info\']}</a><br />\n	 &middot; <a href=\'{$base_url}act=UserCP&amp;CODE=24\'>{$ibforums->lang[\'m_avatar_info\']}</a><br />\n	 &middot; <a href=\'{$base_url}act=UserCP&amp;CODE=photo\'>{$ibforums->lang[\'m_change_photo\']}</a><br />\n	 </p>\n	 <!-- Options -->\n	 <div class=\'pformstrip\'>{$ibforums->lang[\'m_options\']}</div>\n	 <p>\n	 <!--IBF.OPTION_LINKS-->\n	 &middot; <a href=\'{$base_url}act=UserCP&amp;CODE=02\'>{$ibforums->lang[\'m_email_opt\']}</a><br />\n	 &middot; <a href=\'{$base_url}act=UserCP&amp;CODE=04\'>{$ibforums->lang[\'m_board_opt\']}</a><br />\n	 &middot; <a href=\'{$base_url}act=UserCP&amp;CODE=06\'>{$ibforums->lang[\'m_skin_lang\']}</a><br />\n	 &middot; <a href=\'{$base_url}act=UserCP&amp;CODE=08\'>{$ibforums->lang[\'m_email_change\']}</a><br />\n	 &middot; <a href=\'{$base_url}act=UserCP&amp;CODE=28\'>{$ibforums->lang[\'m_passy_opt\']}</a>\n	 </p>\n </td>\n <td style=\'padding:2px\'><!-- --></td>\n<!-- Start main CP area -->\n <td id=\"ucpcontent\" valign=\"top\">\n  <div class=\'maintitle\'>{$ibforums->lang[\'welcome\']}</div>            \n			     \n', 'Menu_bar', '$base_url', 1779380964, 0),
