(3373, 1, 'skin_ucp', '\n<tr>\n <td align=\'center\' class=\'titlemedium\' valign=\'middle\' colspan=\'6\'><input type=\'submit\' class=\'forminput\' value=\'{$ibforums->lang[\'subs_delete\']}\'>&nbsp;&nbsp;{$ibforums->lang[\'with_selected\']}</td>\n</tr>\n</table>\n</div>\n</form>\n<div align=\"right\" style=\"padding:5px\"><i>$text</i></div>\n<div align=\"right\" style=\"padding:5px\">\n 	<form action=\'{$ibforums->base_url}act=UserCP&amp;CODE=26\' method=\'post\'>\n 	{$ibforums->lang[\'show_topics_from\']} <select class=\'forminput\' name=\'datecut\'>$days</select>\n 	<input type=\'submit\' class=\'forminput\' value=\'{$ibforums->lang[\'jmp_go\']}\'>\n 	</form>\n</div>\n', 'subs_end', '$text=\"\", $days=\"\"', 1779380964, 0),
