(3439, 1, 'skin_post', '\n<table class=\'tablefill\' cellpadding=\'4\' align=\'center\' style=\"font-family: \'Nunito\', sans-serif; border-collapse: separate; border-spacing: 10px;\">\n    <tr>\n        <td align=\"center\" style=\"font-weight: bold; font-size: 14px; padding-bottom: 5px;\">\n            {$ibforums->lang[\'click_smilie\']}\n        </td>\n    </tr>\n    <tr>\n        <td align=\"center\">\n            <!-- Modern Emoji Grid -->\n            <div style=\"display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; font-size: 18px;\">\n                <a href=\"javascript:void(0)\" onclick=\"emoticon(\'ðŸ˜€\')\" style=\"text-decoration: none;\">ðŸ˜€</a>\n                <a href=\"javascript:void(0)\" onclick=\"emoticon(\'ðŸ˜‚\')\" style=\"text-decoration: none;\">ðŸ˜‚</a>\n                <a href=\"javascript:void(0)\" onclick=\"emoticon(\'ðŸ™„\')\" style=\"text-decoration: none;\">ðŸ™„</a>\n                <a href=\"javascript:void(0)\" onclick=\"emoticon(\'ðŸ˜Ž\')\" style=\"text-decoration: none;\">ðŸ˜Ž</a>\n                <a href=\"javascript:void(0)\" onclick=\"emoticon(\'ðŸ‘\')\" style=\"text-decoration: none;\">ðŸ‘</a>\n                <a href=\"javascript:void(0)\" onclick=\"emoticon(\'ðŸ”¥\')\" style=\"text-decoration: none;\">ðŸ”¥</a>\n                <a href=\"javascript:void(0)\" onclick=\"emoticon(\'ðŸ¤”\')\" style=\"text-decoration: none;\">ðŸ¤”</a>\n                <a href=\"javascript:void(0)\" onclick=\"emoticon(\'ðŸ˜®\')\" style=\"text-decoration: none;\">ðŸ˜®</a>\n                <a href=\"javascript:void(0)\" onclick=\"emoticon(\'ðŸ˜¢\')\" style=\"text-decoration: none;\">ðŸ˜¢</a>\n                <a href=\"javascript:void(0)\" onclick=\"emoticon(\'ðŸŽ‰\')\" style=\"text-decoration: none;\">ðŸŽ‰</a>\n                <a href=\"javascript:void(0)\" onclick=\"emoticon(\'â¤ï¸\')\" style=\"text-decoration: none;\">â¤ï¸</a>\n                <a href=\"javascript:void(0)\" onclick=\"emoticon(\'âœ¨\')\" style=\"text-decoration: none;\">âœ¨</a>\n                <a href=\"javascript:void(0)\" onclick=\"emoticon(\'ðŸš€\')\" style=\"text-decoration: none;\">ðŸš€</a>\n                <a href=\"javascript:void(0)\" onclick=\"emoticon(\'ðŸ’¯\')\" style=\"text-decoration: none;\">ðŸ’¯</a>\n                <a href=\"javascript:void(0)\" onclick=\"emoticon(\'ðŸ™Œ\')\" style=\"text-decoration: none;\">ðŸ™Œ</a>\n            </div>\n        </td>\n    </tr>\n    <tr>\n        <td align=\"center\" style=\"padding-top: 10px; border-top: 1px solid #eee;\">\n            <!-- Triggers the full TinyMCE emoji picker -->\n            <b><a href=\"javascript:void(0)\" onclick=\"tinymce.execCommand(\'mceEmoticons\');\" style=\"color: #004a99; text-decoration: underline;\">\n                {$ibforums->lang[\'all_emoticons\']}\n            </a></b>\n        </td>\n    </tr>\n</table>\n', 'smilie_table', '', 1779380964, 0),
