(3459, 1, 'skin_forum', '\n    <!-- Begin Pinned Topic Entry {$data[\'tid\']} -->\n    <tr> \n      <td align=\'center\' class=\'row4\'><a href=\"{$ibforums->base_url}act=fav&topic={$data[\'tid\']}\" title=\"Add to favorites\">{$data[\'folder_img\']}</a></td>\n      <td align=\'center\' class=\'row2\'>{$data[\'topic_icon\']}</td>\n      \n      <td class=\'row2 {$f_class} forum-row\'>\n       {$data[\'go_new_post\']}<b>{$data[\'prefix\']}</b> <a href=\'{$ibforums->base_url}showtopic={$data[\'tid\']}\' class=\'linkthru\' title=\'{$ibforums->lang[\'topic_started_on\']} {$data[\'start_date\']}\'>{$data[\'title\']}  {$data[\'PAGES\']}</a>\n        <br /><span class=\'desc\'>{$data[\'description\']}</span></td>\n      <td align=\'center\' class=\'row4\'>{$data[\'starter\']}</td>\n      <td align=\'center\' class=\'row4\'>{$data[\'posts\']}</td>\n      <td align=\'center\' class=\'row4\'>{$data[\'views\']}</td>\n      <td align=\'center\' class=\'row4\'>{$data[\'rating\']}</td>\n      <td class=\'row4\'><span class=\'desc\'>{$data[\'last_post\']}<br /><a href=\'{$ibforums->base_url}showtopic={$data[\'tid\']}&amp;view=getlastpost\'>{$data[\'last_text\']}</a> <b>{$data[\'last_poster\']}</b></span></td>\n    </tr>\n    <!-- End Pinned Topic Entry {$data[\'tid\']} -->\n', 'render_pinned_row', '$data', 1779380964, 0),
(3460, 1, 'skin_profile', '\n  <tr>\n	<td class=\"row3\" valign=\'top\'><b>{$ibforums->lang[\'warn_level\']}</b></td>\n	<td align=\'left\' class=\'row1\'><a href=\"javascript:PopUp(\'{$ibforums->base_url}act=warn&amp;mid={$mid}&amp;CODE=view\',\'Pager\',\'500\',\'450\',\'0\',\'1\',\'1\',\'1\')\">{$percent}</a>%: <a href=\'{$ibforums->base_url}act=warn&amp;type=minus&amp;mid={$mid}\' title=\'{$ibforums->lang[\'tt_warn_minus\']}\'><{WARN_MINUS}></a>{$img}<a href=\'{$ibforums->base_url}act=warn&amp;type=add&amp;mid={$mid}\' title=\'{$ibforums->lang[\'tt_warn_add\']}\'><{WARN_ADD}></a>\n</td>\n  </tr>\n', 'warn_level', '$mid, $img, $percent', 1779380964, 0),
