(3463, 1, 'skin_profile', '\n <tr>\n	<td class=\"row3\" valign=\'top\'><b>{$ibforums->lang[\'rating_level\']}</b></td>\n	<td align=\'left\' class=\'row1\'>&lt;&nbsp;$min ( <a href=\"javascript:PopUp(\'{$ibforums->base_url}act=warn&amp;mid={$mid}&amp;CODE=view\',\'Pager\',\'500\',\'450\',\'0\',\'1\',\'1\',\'1\')\">{$level}</a> ) $max&nbsp;&gt;</td>\n  </tr>\n', 'warn_level_rating_no_mod', '$mid, $level,$min=0,$max=10', 1779380964, 0),
